"Урок 17. Природные явления. Земля": "Leçon 17. Phénomènes naturels. La Terre",
"Природные явления. Земля": "Phénomènes naturels. La Terre",
"Называть ударные инструменты и делить их на группы, узнавать музыку Эдварда Грига о природе.": "Nommer les instruments à percussion et les classer en groupes, reconnaître la musique d'Edvard Grieg sur la nature.",
"Природные явления": "Phénomènes naturels",
"Снег, дождь, солнце, тучи — всё это природные явления. Некоторые из них сопровождаются звуками, и их можно передать в музыке.": "La neige, la pluie, le soleil, les nuages : tout cela, ce sont des phénomènes naturels. Certains s'accompagnent de bruits, et on peut les représenter en musique.",
"Ударные инструменты": "Instruments à percussion",
"Ударные инструменты — это инструменты, у которых звук получается с помощью удара. По-казахски они называются «соқпалы аспаптар».": "Les instruments à percussion sont des instruments dont le son est produit en frappant. En kazakh, on les appelle « соқпалы аспаптар ».",
"Две группы ударных": "Deux groupes de percussions",
"Ударные делят на две группы: с неопределённой высотой звука (тарелки, барабаны) и с определённой высотой звука (ксилофон, челеста).": "On divise les percussions en deux groupes : à hauteur de son indéterminée (cymbales, tambours) et à hauteur de son déterminée (xylophone, célesta).",
"Эдвард Григ": "Edvard Grieg",
"Эдвард Григ — норвежский композитор. Он написал сюиту «Пер Гюнт» к театральной пьесе Генрика Ибсена.": "Edvard Grieg est un compositeur norvégien. Il a écrit la suite « Peer Gynt » pour la pièce de théâtre d'Henrik Ibsen.",
"Сюита «Пер Гюнт»": "La suite « Peer Gynt »",
"В ней есть пьесы «Утро» и «В пещере горного короля». Григ показывает в музыке утреннюю природу и жителей подземного царства.": "Elle contient les pièces « Le Matin » et « Dans l'antre du roi de la montagne ». Grieg montre en musique la nature au matin et les habitants du royaume souterrain.",
"Природа и инструменты": "La nature et les instruments",
