"Различать подгруппы струнных инструментов и называть произведения о воде и грозе.": "Distinguer les sous-groupes d'instruments à cordes et nommer des œuvres sur l'eau et l'orage.",
"Струнные инструменты": "Instruments à cordes",
"Это самая многочисленная группа инструментов. Их называют основой симфонического оркестра.": "C'est le groupe d'instruments le plus nombreux. On les appelle la base de l'orchestre symphonique.",
"Народные струнные": "Cordes populaires",
"Семейство народных струнных инструментов тоже очень разнообразно. Все струнные инструменты в мире условно делят на три подгруппы.": "La famille des instruments à cordes populaires est aussi très variée. Tous les instruments à cordes du monde sont divisés, en gros, en trois sous-groupes.",
"Щипковые": "Les instruments à cordes pincées",
"Звук получают, защипывая струну пальцами или специальной пластинкой — плектром. Это домбра, гитара, арфа.": "Le son est produit en pinçant la corde avec les doigts ou avec une petite plaque spéciale, le plectre. Ce sont la dombra, la guitare, la harpe.",
"Смычковые и ударные": "Cordes frottées et cordes frappées",
"У смычковых звук извлекают смычком из конского волоса: виолончель, кобыз. У ударных по струнам бьют палочками или молоточками: фортепиано, цимбалы.": "Pour les cordes frottées, on produit le son avec un archet en crin de cheval : le violoncelle, le kobyz. Pour les cordes frappées, on frappe les cordes avec des baguettes ou des petits marteaux : le piano, le cymbalum.",
"Эолова арфа": "La harpe éolienne",
"Её струны звучат от колебания воздуха, и музыкант ей не нужен. Это деревянный ящик с отверстием, внутри которого натянуты струны.": "Ses cordes sonnent grâce aux vibrations de l'air, et il n'y a pas besoin de musicien. C'est une caisse en bois percée d'un trou, à l'intérieur de laquelle sont tendues des cordes.",
"Разложи струнные инструменты по подгруппам": "Range les instruments à cordes par sous-groupes",
"Определи, к какой подгруппе относится инструмент или способ звукоизвлечения.": "Détermine à quel sous-groupe appartient l'instrument ou la façon de produire le son.",
"В какую подгруппу относится?": "À quel sous-groupe cela appartient-il ?",
