"Называть группы духовых инструментов и объяснять, что такое сценические эффекты.": "Nommer les groupes d'instruments à vent et expliquer ce que sont les effets de scène.",
"Духовые инструменты": "Instruments à vent",
"Это инструменты, которые звучат благодаря воздуху, который вдувает музыкант. Они делятся на три группы: медные, деревянные и клавишные.": "Ce sont des instruments qui sonnent grâce à l'air que le musicien souffle dedans. Ils se divisent en trois groupes : les cuivres, les bois et les instruments à clavier.",
"Медные и деревянные": "Cuivres et bois",
"К медным относятся труба, валторна, туба, горн, фанфары. К деревянным — дудка, флейта, саксофон, кларнет, фагот, балабан и зурна.": "Parmi les cuivres, il y a la trompette, le cor, le tuba, le clairon, les fanfares. Parmi les bois : la flûte simple, la flûte, le saxophone, la clarinette, le basson, le balaban et la zurna.",
"Клавишные духовые": "Vents à clavier",
"К клавишным духовым относятся фисгармония, аккордеон, мелодика, баян и орган.": "Parmi les vents à clavier, il y a l'harmonium, l'accordéon, la mélodica, le bayan et l'orgue.",
"Сценические эффекты": "Effets de scène",
"Так называют звуковое и световое сопровождение, иллюзии движения и превращения в спектакле, концерте или шоу. Слово пришло из латыни и означает «исполнение».": "C'est le nom qu'on donne à l'accompagnement sonore et lumineux, aux illusions de mouvement et de transformation dans un spectacle, un concert ou un show. Le mot vient du latin et signifie « exécution ».",
"Рихард Вагнер": "Richard Wagner",
"Немецкий композитор и дирижёр (1813–1883). Его музыка «Полёт валькирий» рисует приближение крылатых коней. Помогают в этом динамические оттенки.": "Compositeur et chef d'orchestre allemand (1813–1883). Sa musique « La Chevauchée des Walkyries » dépeint l'approche de chevaux ailés. Les nuances dynamiques y aident.",
