"Природные явления. Огонь": "Phénomènes naturels. Le feu",
"Различать, как музыка передаёт дикий и укрощённый огонь, и называть произведения С. Прокофьева и П.И. Чайковского.": "Distinguer comment la musique représente le feu sauvage et le feu apprivoisé, et nommer des œuvres de S. Prokofiev et de P. I. Tchaïkovski.",
"Огненный смерч": "La tornade de feu",
"Это очень яркое, но очень опасное природное явление. Чаще всего оно возникает в горящем лесу, а ветер там сильнее 160 километров в час.": "C'est un phénomène naturel très lumineux, mais très dangereux. Le plus souvent, il apparaît dans une forêt en flammes, et le vent y dépasse 160 kilomètres à l'heure.",
"Прокофьев и «Каменный цветок»": "Prokofiev et « La Fleur de pierre »",
"Композитор С. Прокофьев в балете «Каменный цветок» изобразил музыкой похожее явление. Танец Огневушки-поскакушки передаёт неуправляемый характер огненного вихря.": "Dans le ballet « La Fleur de pierre », le compositeur S. Prokofiev a représenté en musique un phénomène semblable. La danse de la Petite Flamme sauteuse rend le caractère incontrôlable du tourbillon de feu.",
"Укрощённый огонь": "Le feu apprivoisé",
"Человек научился управлять огнём: он обогревает и освещает жильё. Такой огонь спокойный и доброжелательный.": "L'être humain a appris à maîtriser le feu : il chauffe et éclaire la maison. Ce feu est calme et bienveillant.",
"Чайковский и «У камелька»": "Tchaïkovski et « Au coin du feu »",
"Пьеса «У камелька» входит в цикл «Времена года» П.И. Чайковского. В ней музыка передаёт спокойный, добрый огонь и чувство тепла.": "La pièce « Au coin du feu » fait partie du cycle « Les Saisons » de P. I. Tchaïkovski. Dans cette pièce, la musique rend un feu calme et gentil et la sensation de chaleur.",
"Огонь и безопасность": "Le feu et la sécurité",
"Огонь может стать причиной пожара, поэтому очень важно соблюдать правила пожарной безопасности. Спички — не игрушка, а огонь — не забава!": "Le feu peut causer un incendie, c'est pourquoi il est très important de respecter les règles de sécurité incendie. Les allumettes ne sont pas un jouet, et le feu n'est pas un jeu !",
