"Фантазии природы": "Les fantaisies de la nature",
"Объяснять, что такое программная музыка, и называть примеры музыки, изображающей природу.": "Expliquer ce qu'est la musique à programme et donner des exemples de musique qui représente la nature.",
"Музыкальная живопись": "La peinture en musique",
"Люди всегда делились впечатлениями от увиденного и услышанного. Есть даже выражение «музыкальная живопись» — музыка, которая рисует картины природы.": "Les gens ont toujours partagé leurs impressions de ce qu'ils voyaient et entendaient. Il existe même une expression : « la peinture en musique », c'est une musique qui dessine des tableaux de la nature.",
"Цикл П. Чайковского «Времена года» состоит из 12 пьес. Каждая пьеса — образ одного месяца года, чаще всего через пейзаж.": "Le cycle « Les Saisons » de P. Tchaïkovski se compose de 12 pièces. Chaque pièce est l'image d'un mois de l'année, le plus souvent à travers un paysage.",
"Настроение сезона": "L'ambiance de la saison",
"В небольших пьесах-акварелях отражено настроение сезона: зимние грёзы, весенняя свежесть, летнее раздолье, осенняя грусть.": "Dans ces petites pièces en forme d'aquarelles, on retrouve l'ambiance de la saison : les rêves de l'hiver, la fraîcheur du printemps, la grande liberté de l'été, la tristesse de l'automne.",
"Программная музыка": "La musique à programme",
"Это академическая музыка без слов, то есть инструментальная. Но к ней есть словесное указание на содержание: название или пояснение.": "C'est de la musique classique sans paroles, c'est-à-dire instrumentale. Mais elle est accompagnée d'une indication écrite sur son contenu : un titre ou une explication.",
"Заголовок и эпиграф": "Le titre et l'épigraphe",
"Перед каждой из 12 миниатюр Чайковского есть заголовок и эпиграф — строчки из стихов русских поэтов. Они раскрывают характер музыки. Один из таких эпиграфов взят у А. Майкова.": "Avant chacune des 12 miniatures de Tchaïkovski, il y a un titre et une épigraphe, des lignes tirées de poèmes de poètes russes. Elles révèlent le caractère de la musique. L'une de ces épigraphes vient d'un poème d'A. Maïkov.",
"Кто или что это?": "Qui ou quoi est-ce ?",
"Разложи карточки: произведение, термин или автор.": "Range les cartes : œuvre, terme ou auteur.",
