"Урок 22. Музыка-призыв": "Leçon 22. La musique qui appelle",
"Музыка-призыв": "La musique qui appelle",
"Объяснять, как музыка призывает беречь природу, и называть песни и их авторов.": "Expliquer comment la musique appelle à protéger la nature et nommer des chansons et leurs auteurs.",
"Что такое призыв": "Qu'est-ce qu'un appel",
"Призыв — это обращение, которое зовёт к действию. По-казахски это «шакыру», по-английски — «call».": "Un appel est une demande qui invite à agir. En kazakh, c'est « shakyru », en anglais, « call ».",
"Музыка, которая зовёт": "La musique qui invite",
"Многие музыкальные произведения не просто украшают нашу жизнь. Они становятся руководством к действию и помогают человеку сделать правильный выбор.": "Beaucoup d'œuvres musicales ne se contentent pas d'embellir notre vie. Elles deviennent un guide pour agir et aident la personne à faire le bon choix.",
"Экологическая тема": "Le thème écologique",
"В музыке бывает экологическая тема — это охрана окружающей среды. Песни напоминают нам, что природу нужно беречь.": "En musique, il existe un thème écologique : la protection de l'environnement. Les chansons nous rappellent qu'il faut protéger la nature.",
"«Песня о земной красоте»": "« Chanson sur la beauté de la terre »",
"Эту песню написал Я. Дубравин. Она о красоте природы и о доброте, которой нужно делиться.": "Cette chanson a été écrite par Y. Doubravine. Elle parle de la beauté de la nature et de la bonté qu'il faut partager.",
"«Не дразните собак»": "« Ne taquinez pas les chiens »",
"Эта песня из кинофильма «Происшествие». Музыку написал Е. Птичкин, слова — М. Пляцковский. Песня призывает добро относиться к животным и красоте земли.": "Cette chanson vient du film « L'Incident ». La musique a été écrite par E. Ptichkine et les paroles par M. Plyatskovski. La chanson appelle à être gentil avec les animaux et à respecter la beauté de la terre.",
"Береги природу": "Protège la nature",
"Барсик спрашивает: что помогает природе и животным, а что им вредит? Разложи карточки.": "Barsik demande : qu'est-ce qui aide la nature et les animaux, et qu'est-ce qui leur fait du mal ? Range les cartes.",
"Так поступает друг природы": "Voilà ce que fait un ami de la nature",
"Так поступать нельзя": "Voilà ce qu'il ne faut pas faire",
"Посадить дерево": "Planter un arbre",
"Пословица говорит: кто не сажал дерева, тому не лежать в тени.": "Le proverbe dit : celui qui n'a jamais planté d'arbre ne se reposera pas à son ombre.",
"Беречь молодую поросль": "Protéger les jeunes pousses",
"Из неё вырастут большие деревья.": "Elles deviendront de grands arbres.",
"Насыпать птицам зерно и крошки": "Verser des graines et des miettes aux oiseaux",
"Так мы заботимся о птицах.": "C'est ainsi que nous prenons soin des oiseaux.",
"Любоваться красотой земли и беречь её": "Admirer la beauté de la terre et la protéger",
"Это призыв песни о земной красоте.": "C'est l'appel de la chanson sur la beauté de la terre.",
"Дразнить собак": "Taquiner les chiens",
"Песня призывает так не делать.": "La chanson appelle à ne pas le faire.",
"Гонять кошек": "Chasser les chats",
"Животных нельзя обижать.": "Il ne faut pas faire de mal aux animaux.",
"Пугать жуков": "Faire peur aux scarabées",
