"Мой любимец": "Mon petit compagnon",
"Объяснять, что такое нотное переложение, и называть музыкальные произведения о любимых животных.": "Expliquer ce qu'est une transcription musicale et nommer des œuvres musicales sur les animaux que l'on aime.",
"Конь в музыке": "Le cheval en musique",
"У казахского народа самым любимым и почитаемым животным всегда был конь, скакун. Многие композиторы рисовали музыкой его стремительные, неудержимые скачки.": "Pour le peuple kazakh, le cheval, le coursier, a toujours été l'animal le plus aimé et le plus respecté. Beaucoup de compositeurs ont dessiné en musique ses galops rapides et irrésistibles.",
"Курмангазы и «Адай»": "Kurmangazy et « Adaï »",
"Великий казахский композитор Курмангазы создал музыкальную картину «Адай». В ней не просто скачки: он показал мужественный, героический дух древнего казахского рода Адай.": "Le grand compositeur kazakh Kurmangazy a créé le tableau musical « Adaï ». Il n'y a pas seulement des galops : il y montre l'esprit courageux et héroïque de l'ancien clan kazakh des Adaï.",
"Одно произведение — разное исполнение": "Une œuvre, des interprétations différentes",
"Кюй «Адай» можно услышать в трёх исполнениях: на домбре, в оркестре и с электронными инструментами. Произведение одно, а исполнение разное.": "Le kuy « Adaï » peut s'écouter dans trois interprétations : à la dombra, par un orchestre et avec des instruments électroniques. L'œuvre est la même, mais l'interprétation est différente.",
"Что такое переложение": "Qu'est-ce qu'une transcription",
"Переложение — это музыкальное произведение, изложенное в иной форме. Барсик говорит: мелодия та же, а звучит по-новому!": "Une transcription est une œuvre musicale présentée sous une autre forme. Barsik dit : la mélodie est la même, mais elle sonne de façon nouvelle !",
"Песни о любимцах и о мире": "Des chansons sur les petits compagnons et sur le monde",
"У всех народов мира есть песни о домашних любимцах, например английская народная песня «Котятки и перчатки». А песня Л. Квинт «Здравствуй, мир» — о жеребёнке и о мире вокруг. Слово «мир» по-казахски — әлем.": "Tous les peuples du monde ont des chansons sur les animaux de compagnie, par exemple la chanson populaire anglaise « Les petits chats et les mitaines ». Et la chanson « Bonjour, monde » de L. Kvint parle d'un poulain et du monde qui nous entoure. Le mot « monde » se dit « alem » en kazakh.",
"Чья это песня или кюй?": "À qui est cette chanson ou ce kuy ?",
