"Концерт": "Concert",
"Концерт — это выступление музыкантов перед слушателями. По-казахски так же: концерт, по-английски — concert.": "Un concert est une représentation de musiciens devant des spectateurs. En kazakh, c'est pareil : « concert », en anglais, « concert ».",
"Концертная программа": "Programme de concert",
"Это перечень музыкальных произведений и композиций, который заявляют исполнители и организаторы на определённый концерт.": "C'est la liste des œuvres et des morceaux de musique annoncée par les artistes et les organisateurs pour un concert précis.",
"Интересная программа": "Un programme intéressant",
"Все номера должны быть исполнены качественно: слова отчётливы и понятны, мелодии звучат чисто, движения отработаны.": "Tous les numéros doivent être bien exécutés : les paroles sont nettes et compréhensibles, les mélodies sonnent juste, les mouvements sont bien travaillés.",
"Романс": "Romance",
"Романс — небольшое музыкальное сочинение для голоса в сопровождении инструмента, чаще фортепиано. Он написан на стихи лирического содержания.": "Une romance est une petite composition musicale pour la voix accompagnée d'un instrument, le plus souvent le piano. Elle est écrite sur des vers au contenu lyrique.",
"Сергей Рахманинов": "Sergueï Rachmaninov",
