"Объяснять, как кюи Курмангазы и народные песни отражают любовь к Родине, и называть, что нужно беречь.": "Expliquer comment les kuys de Kurmangazy et les chansons populaires expriment l'amour de la Patrie, et dire ce qu'il faut protéger.",
"Родина": "Patrie",
"Родина по-казахски — Отан, по-английски — Homeland. Это страна, где мы живём и которую любим.": "Patrie se dit en kazakh Otan, en anglais Homeland. C'est le pays où nous vivons et que nous aimons.",
"Любовь к Родине": "L'amour de la Patrie",
"В народе говорят, что любовь к Родине начинается у семейного очага, то есть в семье и дома.": "On dit dans le peuple que l'amour de la Patrie commence au foyer familial, c'est-à-dire dans la famille et à la maison.",
"Красота родного края": "La beauté de la terre natale",
"В песнях, кюях, сказаниях и сказках авторы воспевали красоту родного края и призывали сохранять и оберегать её.": "Dans les chansons, les kuys, les légendes et les contes, les auteurs ont chanté la beauté de leur terre natale et ont appelé à la préserver et à la protéger.",
"Кюй «Алатау»": "Le kui « Alatau »",
"Композитор Курмангазы Сагырбайулы изобразил в кюе величественные горные вершины и красивую природу Заилийского Алатау. Кюй можно услышать в исполнении на домбре и в оркестровом варианте.": "Le compositeur Kurmangazy Sagyrbaïouly a représenté dans un kuy les majestueux sommets montagneux et la belle nature du Zailiyski Alatau. On peut entendre ce kuy joué à la dombra et dans une version pour orchestre.",
"Что мы бережём": "Ce que nous protégeons",
"Люди стараются сохранить не только природные богатства, но и культурное наследие своего народа. Песня «Наурыз жыры» (музыка М. Жаманкуловой) — о празднике Наурыз.": "Les gens s'efforcent de préserver non seulement les richesses naturelles, mais aussi le patrimoine culturel de leur peuple. La chanson « Nauryz jyry » (musique de M. Zhamankulova) parle de la fête de Nauryz.",
"Разложи по произведениям": "Classe selon les œuvres",
"Барсик просит разобраться, что относится к кюю, а что к песне.": "Barsik demande de trier ce qui appartient au kuy et ce qui appartient à la chanson.",
"К какому произведению относится?": "De quelle œuvre s'agit-il ?",
"Песня «Наурыз жыры»": "La chanson « Nauryz jyry »",
