"Это горы, красоту которых передаёт кюй.": "Ce sont les montagnes dont le kuy fait ressentir la beauté.",
"Есть домбровый и оркестровый варианты": "Il existe une version pour dombra et une version pour orchestre",
"Его можно услышать в разном исполнении.": "On peut l'entendre dans différentes interprétations.",
