"Урок 26. Как прекрасен этот мир": "Leçon 26. Que ce monde est beau",
"Как прекрасен этот мир": "Que ce monde est beau",
"Объяснять, как с помощью музыкальных произведений можно показать красоту окружающего мира и призвать беречь его.": "Expliquer comment des œuvres musicales peuvent montrer la beauté du monde qui nous entoure et appeler à le protéger.",
"Берегём мир": "Protégeons le monde",
"Если все люди на планете будут беречь и охранять окружающую среду, то мир вокруг нас будет ярким и многообразным.": "Si tous les habitants de la planète protègent et préservent l'environnement, le monde autour de nous sera lumineux et varié.",
"Путешествие": "Le voyage",
"Слово «путешествие» по-казахски «саяхат», а по-английски «voyage». Музыка тоже может отправить нас в путешествие по красивым местам.": "Le mot « voyage » se dit « sayahat » en kazakh et « voyage » en anglais. La musique aussi peut nous emmener en voyage dans de beaux endroits.",
"Песня Д. Тухманова": "La chanson de D. Toukhmanov",
"Песня «Как прекрасен этот мир» написана композитором Д. Тухмановым. В ней важно услышать, как солирующий голос и подголоски дополняют друг друга.": "La chanson « Que ce monde est beau » a été écrite par le compositeur D. Toukhmanov. Il est important d'y entendre comment la voix soliste et les voix d'accompagnement se complètent.",
"Поющий бархан": "La dune chantante",
"«Поющий бархан» — природная достопримечательность Казахстана. Он находится в 180 км от города Алматы, на территории Государственного Национального природного парка «Алтынемель».": "La « dune chantante » est un site naturel remarquable du Kazakhstan. Elle se trouve à 180 km de la ville d'Almaty, sur le territoire du parc national naturel d'État « Altynemel ».",
"Экологический туризм": "L'écotourisme",
"Термин «экологический туризм» в 1983 году ввёл мексиканский экономист-эколог Гектор Цебаллос-Ласкурейн. Он призывал туристов не оставлять после отдыха загрязнения и уважать культурные традиции народа.": "Le terme « écotourisme » a été introduit en 1983 par l'économiste écologue mexicain Héctor Ceballos-Lascuráin. Il demandait aux touristes de ne pas laisser de pollution après leurs vacances et de respecter les traditions culturelles du peuple.",
"Разложи темы по страницам журнала": "Classe les thèmes par pages du magazine",
"Устный журнал «Как прекрасен этот мир» состоит из страниц, и у каждой своя тема. Определи, к какой странице относится сообщение.": "Le magazine oral « Que ce monde est beau » est composé de pages, et chacune a son thème. Détermine à quelle page appartient le message.",
