"17-сабақ. Музыкадағы таң көріністері": "Leçon 17. Les images de l'aube dans la musique",
"Музыкадағы таң көріністері": "Les images de l'aube dans la musique",
"Музыкадағы таң көріністерін сипаттап, М. Мусоргскийдің, Э. Григтің және С. Еркімбековтің шығармаларын ажырата білу.": "Savoir décrire les images de l'aube dans la musique et distinguer les œuvres de M. Moussorgski, d'E. Grieg et de S. Erkimbekov.",
"Композиторға не әсер етеді?": "Qu'est-ce qui inspire un compositeur ?",
"Композиторлар шабыттан, қиялдан, туған жеріне, халқына және табиғатына деген сүйіспеншіліктен шығарма жазады. Біз сүйіспеншілігімізді сөзбен айтсақ, олар музыкамен баяндайды.": "Les compositeurs écrivent des œuvres par inspiration, par imagination, par amour pour leur terre natale, leur peuple et leur nature. Là où nous exprimons notre amour par des mots, eux le racontent avec la musique.",
"Модест Петрович Мусоргский (1839–1881) — орыстың ұлы композиторы. Ол «Хованщина» операсына жазған «Мәскеу өзеніндегі таң» кіріспесімен танымал: онда арайлап атқан таң бейнеленеді.": "Modeste Petrovitch Moussorgski (1839–1881) est un grand compositeur russe. Il est célèbre pour le prélude « L'aube sur la Moskova » de son opéra « La Khovanchtchina » : on y voit l'aube qui se lève et rougeoie.",
"Эдвард Григ (1843–1907) — Норвегияның әйгілі композиторы, пианист, дирижёр. Ол «Пер Гюнт» сюитасының «Таң» шығармасында туған жерінің табиғатын, таң шапағын көркемдеуіш құралдар арқылы суреттеген.": "Edvard Grieg (1843–1907) est un célèbre compositeur, pianiste et chef d'orchestre norvégien. Dans « Le Matin » de la suite « Peer Gynt », il a dépeint la nature de son pays natal et les rayons de l'aube avec des moyens expressifs.",
"С. Еркімбеков": "S. Erkimbekov",
"Серік Еркімбеков — белгілі композитор, ҚР еңбек сіңірген қайраткері. Оның «Отан таңы» шығармасы туған жердің сұлулығын көрсетеді.": "Serik Erkimbekov est un compositeur connu, Homme émérite du Kazakhstan. Son œuvre « L'aube de la Patrie » montre la beauté de la terre natale.",
"Жаңа сөздер": "Mots nouveaux",
"Опера — вокалдық және аспаптық музыканы, театр өнерін біріктіретін жанр. Сюита — бір идеяға бағындырылған әртүрлі пьесалардан құралған шығарма. Интерпретация — орындаушының шығарманы көркем түсіндіруі.": "L'opéra est un genre qui réunit la musique vocale et instrumentale et l'art du théâtre. La suite est une œuvre composée de différentes pièces unies par une même idée. L'interprétation est l'explication artistique d'une œuvre par l'interprète.",
