"Айту: А.Н. Скрябиннің «Прометей» симфониялық поэмасы мен «Жалын биі», «Жел» шығармаларында от пен жел қалай бейнеленетінін түсіндіру.": "Expliquer : comment le feu et le vent sont représentés dans le poème symphonique « Prométhée » d'A. N. Scriabine et dans les œuvres « La danse de la flamme » et « Le vent ».",
"От — өмір символы": "Le feu, symbole de vie",
"Адам отсыз өмір сүре алмайды. От ежелден өмірдің және жылулықтың символы болып саналады.": "L'homme ne peut pas vivre sans feu. Depuis toujours, le feu est considéré comme le symbole de la vie et de la chaleur.",
"«Прометей» поэмасы": "Le poème « Prométhée »",
"Бұл — А.Н. Скрябиннің симфониялық поэмасы. Оның екінші аты — «Поэма огня», яғни «От туралы поэма». Ол 1910 жылы жазылған.": "C'est un poème symphonique d'A. N. Scriabine. Son autre nom est « Poème du feu ». Il a été écrit en 1910.",
"Прометей туралы аңыз": "La légende de Prométhée",
"Поэма ежелгі грек аңызына негізделген. Прометей Олимптен отты рұқсатсыз алып кетіп, адамдарға сыйлаған. Сол үшін құдайлар оны жартасқа мәңгі байлап қойған.": "Le poème s'appuie sur une ancienne légende grecque. Prométhée a pris le feu de l'Olympe sans permission et l'a offert aux hommes. Pour cela, les dieux l'ont enchaîné pour toujours à un rocher.",
"Жарық партиясы": "La partie de lumière",
"Скрябин оркестрге хор мен «жарық партиясын» қосқан. Композитордың ойынша, музыкамен бірге түрлі түсті прожектор сәулелері ауысып тұруы керек.": "Scriabine a ajouté à l'orchestre un chœur et une « partie de lumière ». Selon le compositeur, des faisceaux de projecteurs de couleurs différentes doivent se succéder avec la musique.",
"Симфониялық поэма": "Le poème symphonique",
"Симфониялық поэма — бір бөлімді симфониялық музыка жанры. Бұл — оркестрге арналған бағдарламалық шығарма.": "Le poème symphonique est un genre de musique symphonique en une seule partie. C'est une œuvre à programme pour orchestre.",
