"Музыка арқылы су мен желдің бейнесін елестетіп, шығармаларды суреттермен және билермен салыстыра білу.": "Savoir imaginer l'eau et le vent grâce à la musique et comparer les œuvres avec des tableaux et des danses.",
"Су мен жел – табиғат құбылыстары": "L'eau et le vent, phénomènes de la nature",
"«Сусыз өмір жоқ», «Жел ауа тазартады» дейді. Әр табиғат құбылысының адам өмірінде өз орны бар.": "On dit : « Il n'y a pas de vie sans eau », « Le vent purifie l'air ». Chaque phénomène de la nature a sa place dans la vie des hommes.",
