"«Жел әуені»": "« La mélodie du vent »",
"Бұл шығарманың да музыкасын С. Еркімбеков жазған. Композитор музыка арқылы желдің уілін бейнелеген.": "La musique de cette œuvre aussi a été écrite par S. Erkimbekov. Le compositeur a représenté avec la musique le souffle du vent.",
"Музыка мен суретті салыстыру": "Comparer la musique et le tableau",
"«Ақ бұлақ әуенін» Ө. Қастеевтің «Өмір-өзен» картинасымен, «Жел әуенін» И.В. Ломанованың «Күзгі жел» картинасымен салыстырамыз. Айырмашылығы мен ұқсастығын табамыз.": "Nous comparons « La mélodie de la source claire » avec le tableau « Vie-fleuve » d'O. Kasteev, et « La mélodie du vent » avec le tableau « Vent d'automne » d'I. V. Lomanova. Nous cherchons les différences et les ressemblances.",
"«Жел» әнінің өлеңін Н. Әлімқұлов, әнін М. Маңғытаев жазған. Оны мәнерлеп орындауға тырысамыз.": "Les paroles de la chanson « Le vent » ont été écrites par N. Alimkoulov, et la musique par M. Mangytaev. Nous essayons de l'interpréter avec expression.",
