"Музыкадағы жыл мезгілдері": "Les saisons dans la musique",
"Жыл мезгілдеріне арналған А. Вивальди концерттерін және оркестр туралы негізгі ұғымдарды (оркестр, дирижёр, партитура, концерт) атай білу.": "Savoir nommer les concertos d'A. Vivaldi consacrés aux saisons et les notions de base sur l'orchestre (orchestre, chef d'orchestre, partition, concert).",
"Жылдың төрт мезгілі": "Les quatre saisons de l'année",
"Қыс, көктем, жаз, күз бірінен кейін бірі ауысып отырады. Әр мезгілдің өз әсемдігі бар, сондықтан оған арнап өлеңдер, әндер мен музыкалық шығармалар жазылған.": "L'hiver, le printemps, l'été et l'automne se succèdent. Chaque saison a sa propre beauté, c'est pourquoi on a écrit pour elle des poèmes, des chansons et des œuvres musicales.",
"Вивальди (1678–1741) – итальян композиторы, асқан шебер скрипкашы, дирижёр. Ол Венеция қаласында дүниеге келген.": "Vivaldi (1678–1741) est un compositeur italien, un violoniste d'un grand talent et un chef d'orchestre. Il est né à Venise.",
"«Жыл мезгілдері» концерттері": "Les concertos « Les Quatre Saisons »",
"Вивальдидің ең танымал шығармасы – «Жыл мезгілдері» деп аталатын скрипкаға арналған төрт концерт. Олар: «Көктем», «Жаз», «Күз», «Қыс».": "L'œuvre la plus célèbre de Vivaldi s'appelle « Les Quatre Saisons » : ce sont quatre concertos pour violon. Ce sont : « Le Printemps », « L'Été », « L'Automne », « L'Hiver ».",
"«Шат көңіл» әні": "La chanson « Joie de vivre »",
"Бұл әннің өлеңін Б. Тәжібаев жазған, әнін С. Еркімбеков шығарған. Ән вальс ырғағымен орындалады, көңілді, жарқын.": "Les paroles de cette chanson ont été écrites par B. Tajibaev, et la musique composée par S. Erkimbekov. La chanson est interprétée sur un rythme de valse, elle est joyeuse et lumineuse.",
"Оркестр және дирижёр": "L'orchestre et le chef d'orchestre",
"Оркестр – музыкалық шығармаларды орындайтын аспаптар ұжымы. Дирижёр – музыканттар ұжымын басқарады және шығарманың әдемі орындалуына жауап береді.": "L'orchestre est un ensemble d'instruments qui jouent des œuvres musicales. Le chef d'orchestre dirige l'ensemble des musiciens et veille à ce que l'œuvre soit bien jouée.",
