"21-сабақ. Музыкадағы жыл мезгілдері (жалғасы)": "Leçon 21. Les saisons dans la musique (suite)",
"Музыкадағы жыл мезгілдері (жалғасы)": "Les saisons dans la musique (suite)",
"Жыл мезгілдері туралы шығармаларды таныру, канон, оркестр, дирижёр, симфониялық поэма және сюита ұғымдарын түсіндіру.": "Reconnaître des œuvres sur les saisons et expliquer les notions de canon, d'orchestre, de chef d'orchestre, de poème symphonique et de suite.",
"Жыл – он екі ай": "L'année – douze mois",
"Жыл мезгілдеріне арналған ән мен музыкалық шығарма көп. Домбырашы, композитор Төлепберген Тоқжанов домбыраға арнап «Жыл – он екі ай» пьесаларын жазған, онда он екі айдың ерекшелігі суреттелген.": "Il existe beaucoup de chansons et d'œuvres musicales sur les saisons. Le dombriste et compositeur Tolepbergen Tokjanov a écrit pour la dombra les pièces « L'année – douze mois », où l'on décrit les particularités des douze mois.",
"«Жұмбақ әуендер» ойыны": "Le jeu « Mélodies mystérieuses »",
"Тыңдалған музыкаға қарай шығарма атын түсі сәйкес келетін қағазбен көрсетесің: «Ақпан – Бұрқасын» – ақ, «Қыркүйек – Күзгі той» – сары, «Сәуір – Көктемгі тамшылар» – жасыл, «Шілде – Жаз биі» – қызыл. Түстерді дұрыс көрсеткен топ жеңімпаз болады.": "Selon la musique entendue, tu indiques le titre de l'œuvre avec la feuille de la couleur correspondante : « Février – La Tempête de neige » – blanc, « Septembre – La Fête d'automne » – jaune, « Avril – Les Gouttes du printemps » – vert, « Juillet – La Danse de l'été » – rouge. L'équipe qui montre correctement les couleurs gagne.",
"Канон": "Le canon",
"Әнді орындаудың бір тәсілі – канон. Әнді топтарға бөліп, шумақты кезектесіп, бірінен кейін бірі бастап айтады. «Жау-жау, жаңбыр!» әнінің сөзін Ш. Сариев, әнін К. Дүйсекеев жазған.": "Une façon d'interpréter une chanson est le canon. On divise la chanson en groupes, et chaque groupe commence le couplet à tour de rôle, l'un après l'autre. Les paroles de la chanson « Pleus, pleus, pluie ! » ont été écrites par Sh. Sariev et la musique par K. Duisekeev.",
"Оркестр – түрлі музыкалық аспаптарда шығармалар орындайтын ұжым. Дирижёр – музыкант-орындаушылар ұжымын басқаратын маман.": "L'orchestre est un ensemble qui joue des œuvres sur différents instruments de musique. Le chef d'orchestre est le spécialiste qui dirige l'ensemble des musiciens interprètes.",
"Симфониялық поэма және сюита": "Poème symphonique et suite",
"Симфониялық поэма – бір бөлімді, симфониялық оркестрге арналған бағдарламалық шығарма. Сюита – бір идеяға бағындырылған, әртүрлі пьесадан құрастырылған музыкалық шығарма.": "Le poème symphonique est une œuvre à programme, en un seul mouvement, écrite pour orchestre symphonique. La suite est une œuvre musicale composée de différentes pièces réunies autour d'une même idée.",
