"22-сабақ. Арал тағдыры — ел тағдыры": "Leçon 22. Le destin de l'Aral, c'est le destin du pays",
"Арал тағдыры — ел тағдыры": "Le destin de l'Aral, c'est le destin du pays",
"Арал мәселесі туралы музыка мен суреттің көмегімен айта білу және Қ. Сайжанның күйін, Т. Шевченконың пейзаждарын, «Аралым» әнін ажырату.": "Savoir parler du problème de l'Aral à l'aide de la musique et de la peinture, et distinguer le kuy de K. Saijan, les paysages de T. Chevtchenko et la chanson « Mon Aral ».",
"Арал мәселесі": "Le problème de l'Aral",
"Арал теңізі тартылып барады. Желмен ұшқан ащы тұз табиғатқа да, адам денсаулығына да зиян келтіреді.": "La mer d'Aral s'assèche. Le sel amer emporté par le vent nuit à la nature comme à la santé des gens.",
"Бүкіл әлемнің қайғысы": "Le chagrin du monde entier",
"Арал мәселесі тек Қазақстан үшін ғана емес, басқа мемлекеттер үшін де өзекті. Отандық және шетелдік ғалымдар Аралды қайта толтыру жолдарын қарастыруда.": "Le problème de l'Aral concerne non seulement le Kazakhstan, mais aussi d'autres États. Des scientifiques du pays et de l'étranger cherchent des moyens de remplir de nouveau l'Aral.",
"«Арал тағдыры» күйі": "Le kuy « Le destin de l'Aral »",
"Бұл — Қ. Сайжанның күйі. Күйдің орындалуы адамның мұңды, қайғылы сезімдерін білдіреді, композитор тыңдаушыға маңызды ойды жеткізуге тырысқан.": "C'est un kuy de K. Saijan. Son interprétation exprime des sentiments tristes et douloureux, et le compositeur a voulu transmettre une idée importante à l'auditeur.",
"Тарас Шевченко": "Taras Chevtchenko",
"Тарас Григорьевич Шевченко (1814–1861) — украиннің әйгілі ақыны әрі суретшісі. 1838 жылы Санкт-Петербург қаласының Көркемсурет академиясын бітірген.": "Taras Grigorievitch Chevtchenko (1814–1861) était un célèbre poète et peintre ukrainien. En 1838, il a terminé l'Académie des beaux-arts de la ville de Saint-Pétersbourg.",
"Шевченко және Арал": "Chevtchenko et l'Aral",
"1848 жылы ол А.И. Бутаковтың басшылығымен Арал теңізін зерттеу экспедициясына қатысып, 350-ден астам пейзаж, портрет салған. Маңғыстау облысындағы Түпқараған ауданының орталығы «Форт-Шевченко» деп аталады.": "En 1848, sous la direction d'A. I. Boutakov, il a participé à l'expédition d'étude de la mer d'Aral et a dessiné plus de 350 paysages et portraits. Le centre du district de Tioupkaragan, dans la région de Mangystau, s'appelle « Fort-Chevtchenko ».",
"Кім туралы немесе кімнің шығармасы?": "De qui parle-t-on, ou de qui est l'œuvre ?",
