"23-сабақ. Ядролық жарылысқа — «Жоқ» дейміз!": "Leçon 23. Non aux explosions nucléaires !",
"Ядролық жарылысқа — «Жоқ» дейміз!": "Non aux explosions nucléaires !",
"Полигон мен радиация ұғымдарын түсіндіру, «Заман-ай» мен «Ядролық жарылысқа — «Жоқ» дейміз!» әндерінің авторларын атау және әндердің мазмұнын сипаттау.": "Expliquer les notions de polygone et de radiation, nommer les auteurs des chansons « Zaman-aï » et « Non aux explosions nucléaires ! » et décrire le contenu de ces chansons.",
"Ядролық қарусыз аймақ": "Une zone sans armes nucléaires",
"Қазақстан өзін «ядролық қарусыз аймақ» деп жариялады. Біздің елдің мақсаты — бейбітшілік пен адамдардың денсаулығын сақтау.": "Le Kazakhstan s'est proclamé « zone sans armes nucléaires ». Le but de notre pays est de préserver la paix et la santé des gens.",
"Декларация": "La Déclaration",
"1991 жылы 28 тамызда Декларация қабылданды. Семей полигоны жабылды, ел атом қаруынан бас тарту жолын жалғастырды.": "Le 28 août 1991, la Déclaration a été adoptée. Le polygone de Semipalatinsk a été fermé, et le pays a poursuivi sa voie de renoncement à l'arme atomique.",
"Полигон": "Le polygone",
"Полигон — қару-жарақ пен әскери техникаға, көбінесе ядролық сынақ жүргізуге арналған арнайы бөлінген және жабдықталған аймақ.": "Un polygone est une zone spécialement réservée et équipée pour les armes et le matériel militaire, le plus souvent pour des essais nucléaires.",
"Радиация": "La radiation",
"Радиация (өткір радиация) — ядролық жарылыс кезінде тарайтын радиоактивті сәулелер.": "La radiation (radiation aiguë) désigne les rayons radioactifs qui se propagent lors d'une explosion nucléaire.",
"Екі ән": "Deux chansons",
"«Заман-ай» әнінің өлеңін Ү. Есдәулет, әнін Т. Мұхамеджанов жазған. «Ядролық жарылысқа — «Жоқ» дейміз!» әнінің өлеңін Р. Наурызбаева, әнін Н. Мирманов жазған.": "Les paroles de la chanson « Zaman-aï » ont été écrites par U. Yesdaulet et la musique par T. Mukhamedjanov. Les paroles de la chanson « Non aux explosions nucléaires ! » ont été écrites par R. Nauryzbaeva et la musique par N. Mirmanov.",
