"Балет пен реквием деген не екенін айту, Ғ. Жұбанованың «Хиросима» балетін және «Сакура» әнін тану.": "Dire ce que sont un ballet et un requiem, reconnaître le ballet « Hiroshima » de G. Joubanova et la chanson « Sakura ».",
"Ғазиза Жұбанова": "Gaziza Joubanova",
"Ғазиза Жұбанова (1927–1993) — композитор. Ол Алматы қаласында музыканттар отбасында дүниеге келген. Әкесі — атақты композитор Ахмет Жұбанов.": "Gaziza Joubanova (1927–1993) était compositrice. Elle est née à Almaty dans une famille de musiciens. Son père était le célèbre compositeur Akhmet Joubanov.",
"Композитордың шығармалары": "Les œuvres de la compositrice",
"Ғ. Жұбанова опера, балет, оратория, ән, хор жазған. Оның «Хиросима» балеті Қазақстан музыка өнерінде үлкен жаңалық болды.": "G. Joubanova a écrit des opéras, des ballets, des oratorios, des chansons et des chœurs. Son ballet « Hiroshima » a été une grande nouveauté dans l'art musical du Kazakhstan.",
"Мемлекеттік сыйлық": "Le prix d'État",
"«Хиросима» балеті үшін Ғ. Жұбановаға 1970 жылы Қазақстанның Мемлекеттік сыйлығы берілді.": "Pour le ballet « Hiroshima », G. Joubanova a reçu en 1970 le Prix d'État du Kazakhstan.",
"Балет": "Le ballet",
"Балет — музыкалық-хореографиялық қойылым. Оның мазмұны, кейіпкерлердің ой-сезімі музыка мен би арқылы көрсетіледі.": "Le ballet est un spectacle musical et chorégraphique. Son contenu et les pensées et sentiments des personnages sont montrés par la musique et la danse.",
"Реквием": "Le requiem",
"Реквием — көпдауысты, қайғылы музыкалық шығарма. «Хиросима» балетінің соңында реквием-гимн естіледі: музыка жер бетінде ешқашан ядролық жарылыстар болмасын деген тілекті жеткізеді.": "Le requiem est une œuvre musicale triste, à plusieurs voix. À la fin du ballet « Hiroshima », on entend un requiem-hymne : la musique exprime le souhait qu'il n'y ait plus jamais d'explosions nucléaires sur la Terre.",
"Кім? Не?": "Qui ? Quoi ?",
