"25-сабақ. Ел қорғауға дайынбыз!": "Leçon 25. Nous sommes prêts à défendre notre pays !",
"Ел қорғауға дайынбыз!": "Nous sommes prêts à défendre notre pays !",
"Атап айту: «Сарбаздар жыры» мен «Мәңгілік алау» балетінің авторларын, тақырыбын және ел қорғау туралы музыканың мәнін түсіндіру.": "Nommer : expliquer qui sont les auteurs et quel est le thème de « La chanson des soldats » et du ballet « La flamme éternelle », et pourquoi la musique est importante pour la défense du pays.",
"Ата-бабалар аманаты": "Le legs des ancêtres",
"Кім болсақ та, қайда жүрсек те, өз туған жерімізді, табиғатымызды аялап, қорғауымыз керек. Бұл — ата-бабаларымыздың бізге қалдырған аманаты.": "Qui que nous soyons, où que nous allions, nous devons aimer et protéger notre terre natale et notre nature. C'est le legs que nos ancêtres nous ont laissé.",
"Табиғатты қорғау": "Protéger la nature",
"Арал теңізі мен Семей полигоны мәселелерін өткен сабақтарда білдік. Жеріміздің табиғатына зиян келіп жатыр, сондықтан елімізді, қоршаған ортаны қорғауға дайын болуымыз керек.": "Nous avons appris les problèmes de la mer d'Aral et du polygone de Semipalatinsk lors des leçons précédentes. La nature de notre terre est en danger, c'est pourquoi nous devons être prêts à protéger notre pays et l'environnement.",
"«Сарбаздар жыры»": "« La chanson des soldats »",
"Бұл — қазақ сарбаздары туралы ән. Өлеңін А. Асылбек жазған, әнін Н. Айтбаева шығарған. Әнде қайырма бар.": "C'est une chanson sur les soldats kazakhs. Les paroles ont été écrites par A. Assylbek et la mélodie composée par N. Aïtbaïeva. La chanson a un refrain.",
"Әннің тақырыбы": "Le thème de la chanson",
"«Сарбаздар жыры» елін қорғайтын батыл сарбаздарды дәріптейді. Ән тыныштық пен бейбіт өмір арманын жеткізеді.": "« La chanson des soldats » célèbre les braves soldats qui défendent leur pays. La chanson exprime le rêve de paix et de vie tranquille.",
"«Мәңгілік алау» балеті": "Le ballet « La flamme éternelle »",
"Бұл — бір актілі балеттен үзінді, музыкасын С. Еркімбеков жазған. Балет 12 нөмірден тұрады және соғыс пен бейбітшілік туралы айтады. Ондағы нөмірлердің бірі — «Реквием».": "C'est un extrait d'un ballet en un acte, dont la musique a été écrite par S. Erkimbekov. Le ballet comprend 12 numéros et parle de la guerre et de la paix. L'un de ses numéros s'appelle « Requiem ».",
