"Қоршаған ортаны қорғайтын мамандықтарды атау, «Атамекен» әні мен «Мәңгілік алау» балетін таныту және кейіпкер, көрініс ұғымдарын түсіндіру.": "Nommer les métiers qui protègent l'environnement, faire connaître la chanson « Atameken » et le ballet « La flamme éternelle », et expliquer les notions de personnage et de scène.",
"«Атамекен» әні": "La chanson « Atameken »",
"Бұл әннің сөзін Ш. Сариев, әнін Ж. Тұяқбаев жазған. Ән Отанымыздың әдемі табиғатын мадақтайды.": "Les paroles de cette chanson ont été écrites par Ch. Sariev et la mélodie par J. Touiakbaïev. La chanson célèbre la belle nature de notre patrie.",
"Төрт топ, төрт мамандық": "Quatre groupes, quatre métiers",
"Сабақта оқушылар төрт топқа бөлінеді: Экологтер, Өртсөндірушілер, Балықшылар және Орманшылар. Әр топ өз мамандығы туралы таныстырылым дайындайды.": "Pendant la leçon, les élèves sont répartis en quatre groupes : les écologistes, les pompiers, les pêcheurs et les forestiers. Chaque groupe prépare une présentation sur son métier.",
"Экологтер мен өртсөндірушілер": "Les écologistes et les pompiers",
"Эколог қоршаған ортамен үйлесімді өмір сүруге көмектеседі. Өртсөндірушілер күні-түні қауіп пен қатерден сақтап, өрт шықса көмекке келеді.": "L'écologiste aide à vivre en harmonie avec l'environnement. Les pompiers nous protègent jour et nuit du danger et des menaces, et viennent à notre secours en cas d'incendie.",
"Балықшылар мен орманшылар": "Les pêcheurs et les forestiers",
"Балықшылар балықтың қасиетін біледі және балық өсетін су ортасының тазалығын сақтайды. Орманшылар орманды қорғап, түрлі міндеттерді атқарады.": "Les pêcheurs connaissent les qualités des poissons et gardent propre le milieu aquatique où vivent les poissons. Les forestiers protègent la forêt et accomplissent diverses tâches.",
"Бұл балеттің музыкасын С. Еркімбеков жазған. Балет — музыкалық-хореографиялық қойылым. Онда кейіпкерлер сөйлемей, би мен музыка арқылы өз ойын көрсетеді.": "La musique de ce ballet a été écrite par S. Erkimbekov. Le ballet est un spectacle musical et chorégraphique. Les personnages n'y parlent pas : ils expriment leurs pensées par la danse et la musique.",
"Кім не істейді?": "Qui fait quoi ?",
"Әр сөйлемді қай мамандыққа жататынын тап.": "Trouve à quel métier appartient chaque phrase.",
"Бұл қай мамандыққа қатысты?": "De quel métier s'agit-il ?",
