"Лаулаған отты сөндіреді.": "Éteint le feu qui flambe.",
"Қауіп пен қатерден сақтайды": "Protège du danger et des menaces",
"Күні-түні дайын тұрады.": "Est prêt jour et nuit.",
"Күні-түні бір тынбай дайын тұрады": "Est prêt jour et nuit sans se reposer",
"Қауіп болса, бірінші болып келеді.": "S'il y a un danger, arrive le premier.",
